use crate::services::features::{FeatureExtractor, ISO_BANDS_HZ, SAMPLE_RATE_HZ};
// Assuming the simulator code is accessible via a path or I can recreate the logic
// For this audit, I will use a direct numerical comparison against the shared spec logic.

#[test]
fn test_feature_parity_numeric_comparison() {
    // 1. Create a 1kHz sine wave test signal
    let freq = 1000.0;
    let duration = 0.5; // 0.5 seconds
    let num_samples = (SAMPLE_RATE_HZ * duration) as usize;
    let samples: Vec<f32> = (0..num_samples)
        .map(|i| (2.0 * std::f32::consts::PI * freq * (i as f32) / SAMPLE_RATE_HZ).sin())
        .collect();

    // 2. Extract production features
    let prod_features = FeatureExtractor::extract(&samples);

    // 3. Define reference calculation logic (from shared_spec.md/simulator)
    // RMS of sine wave = 0.707
    let expected_rms = 0.707;

    // 4. Numerical Comparison
    let rms_error = (prod_features.rms - expected_rms).abs();

    println!("RMS Error: {}", rms_error);

    assert!(rms_error < 0.01, "RMS Parity Failed: Expected {}, got {}", expected_rms, prod_features.rms);

    // Verify 1kHz band dominates (1kHz is index 18 in ISO_BANDS_HZ)
    let max_idx = prod_features.spectral_bands.iter()
        .enumerate()
        .max_by(|a, b| a.1.partial_cmp(b.1).unwrap())
        .map(|(i, _)| i)
        .unwrap();

    assert_eq!(max_idx, 18, "Dominant band parity failed: Expected 18 (1kHz), got {}", max_idx);
}
