use crate::services::features::{FeatureExtractor, SAMPLE_RATE_HZ};
use serde_json::Value;
use std::fs::File;
use std::io::BufReader;

#[test]
fn test_feature_parity_with_reference_data() {
    let file = File::open("../../../experiments/stage_a/parity_reference.json").expect("Failed to open reference file");
    let reader = BufReader::new(file);
    let reference_data: Value = serde_json::from_reader(reader).expect("Failed to parse JSON");

    for signal in reference_data.as_array().unwrap() {
        let samples: Vec<f32> = signal["samples"].as_array().unwrap()
            .iter().map(|v| v.as_f64().unwrap() as f32).collect();
        let expected = &signal["features"];

        let actual = FeatureExtractor::extract(&samples);

        let tol = 1e-3;

        assert!((actual.rms - expected["rms"].as_f64().unwrap() as f32).abs() < tol, "RMS mismatch");
        assert!((actual.peak - expected["peak"].as_f64().unwrap() as f32).abs() < tol, "Peak mismatch");
        assert!((actual.spectral_centroid_hz - expected["spectral_centroid_hz"].as_f64().unwrap() as f32).abs() < tol, "Centroid mismatch");
    }
}
EOF
